from PIL import Image, ImageDraw, ImageOps
im=Image.open('pantomograph.jpg').convert('L')
def g(box,out,step=50,s=2):
    c=im.crop(box); c=ImageOps.autocontrast(c,cutoff=1); d=ImageDraw.Draw(c)
    for x in range(box[0]-box[0]%step+step,box[2],step):
        d.line([(x-box[0],0),(x-box[0],c.size[1])],fill=200 if x%100==0 else 120)
        if x%100==0: d.text((x-box[0]+2,2),str(x),fill=255)
    for y in range(box[1]-box[1]%step+step,box[3],step):
        d.line([(0,y-box[1]),(c.size[0],y-box[1])],fill=200 if y%100==0 else 120)
        if y%100==0: d.text((2,y-box[1]+2),str(y),fill=255)
    c=c.resize((c.size[0]*s,c.size[1]*s)); c.save(out)
g((850,400,1350,720),'/tmp/bulb.png',s=3)
